commit 8c366501eaff731b30a75e5e4e81b8544c04769c
Author: Changming Sun <changmingsun@google.com>
Date:   Sat Jul 25 12:04:04 2026 -0700

    Add global positive-dimension shape product validation to TFLite verifier.

    If any shape is too big, the verifier will reject it. Filter dynamic batch/zero dimensions (dim > 1) to isolate positive dimensions and validate CheckedNumElements for all tensors at model load time up front.

    PiperOrigin-RevId: 953923303

diff --git a/tensorflow/lite/core/tools/verifier.cc b/tensorflow/lite/core/tools/verifier.cc
index f877c19a367..5a9dc17a4cb 100644
--- a/tensorflow/lite/core/tools/verifier.cc
+++ b/tensorflow/lite/core/tools/verifier.cc
@@ -643,6 +643,25 @@ bool VerifyTensors(const Model& model, ErrorReporter* error_reporter) {
       continue;
     }
     for (const auto* tensor : *subgraph->tensors()) {
+      if (tensor->shape()) {
+        std::vector<int> positive_dims;
+        positive_dims.reserve(tensor->shape()->size());
+        // Collect fixed dimensions (> 1) to validate that sub-dimension /
+        // spatial element products do not overflow 32-bit int32_t, even when
+        // batch size is 0 or 1.
+        for (int dim : *tensor->shape()) {
+          if (dim > 1) {
+            positive_dims.push_back(dim);
+          }
+        }
+        int num_elements = 0;
+        if (CheckedNumElements(positive_dims, num_elements) != kTfLiteOk) {
+          ReportError(error_reporter, "Tensor %s dimension overflow",
+                      NameOrEmptyString(tensor->name()));
+          return false;
+        }
+      }
+
       if (!tensor->buffer()) {
         continue;
       }

